    "hi": "पाठों आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं क्षो प्रश्नों के उत्तर लगभग शब्दों में दीजिए : (क) सुखिया संसार है, खायै अरु सोवै । दुखिया दास कबीर है, जागै अरु रौवै । साखी के संदर्भ में कबीर के दुखी और जाग्रत होने का कारण लिखिए । क्या जागना भी दुख का कारण हो सकता है ? स्पष्ट कीजिए । (ख) भमनुष्यता' कविता के आधार लिखिए कि कैसा जीवन जीने वाले लोग मरकर अमर हो जाते हैं । (ग) प्रदेश में पावस! कविता के आधार लिखिए कि झरने का गुणगान क्यों और कैसे कर रहे हैं",
