    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक पूछे गए प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : देश के एक प्रसिद्ध आयुर्विज्ञान संस्थान के बाल रोग विभाग ने बच्चों का दो साल तक गहन अध्ययन किया है । इस अध्ययन में पाँच साल तक के बच्चों को शामिल किया गया था । पता चला कि ये बच्चे एक घंटा से भी अधिक समय मोबाइल बिताते हैं मोबाइल और टीवी का कुल समय पाँच घंटे निकला । यही नहीं, इनके माता पिता भी लगभग साढ़े छह घंटे विभिन्न गैजेट्स बिताते हैं इसी अध्ययन में यह भी पाया गया कि प्रतिशत बच्चे सोने से पहले इन उपकरणों के इस्तेमाल के आदी हो चले हैं । यह भी एक तरह का नशा ही है, जिस अगर समय रहते ध्यान न दिया गया तो यह आदत आने वाली पीढ़ियों के लिए भारी मुसीबत सकती है । विश्व स्वास्थ्य संगठन की स्पष्ट सलाह है कि दो साल तक के बच्चों के हाथों में गैजेट्स या इलैक्ट्रॉनिक उपकरण नहीं देने चाहिए यहाँ तक कि पाँच साल की उप्र में भी इनका स्क्रीन टाइम एक घंटे से अधिक नहीं होना चाहिए । लेकिन संपन्न होते घरों में यह देखने को मिलता है कि इसे वे अपनी हैसियत से जोड़ने लगे हैं । ऐसा करते हुए वे भूल जाते हैं कि वे अपने बच्चों का आज ही नहीं, भविष्य भी बिगाड़ रहे हैं । . निम्नलिखित में से किस कथन को गद्यांश की सीख के आधार के रूप में कहा जा सकता है ?",
