    "hi": "(क) (ख) कृत्रिम बौद्धिकता (आर्टीफीसियल इंटेलीजेंस) के बढ़ते कदम संकेत बिंदु « क्या है कृत्रिम बौद्धिकता « बढ़ता प्रभाव « संभावित खतरा मुझे मेरा निजी स्मार्ट फोन मिला संकेत बिंदु « और क्यों मिला ? अवर्णनीय खुशी का अनुभव « मित्रों और संबंधियों के साथ खुशी बाँटना दैव दैव आलसी पुकारा संकेत बिंदु कथन का अर्थ आलस्य सबसे बड़ा शत्रु से ही सफलता प्रधानाचार्य, क.ख.ग. उच्चतर माध्यमिक विदूयालय की ओर से जिला के मुख्य चिकित्साधिकारी को लगभग शब्दों में एक लिखिए जिसमें विद्यालय के छात्रों के स्वास्थ्य परीक्षण का निवेदन किया गया हो । अथवा आप अपने विद्यालय के रसायन विज्ञान के अध्यापक हैं । रसायन विज्ञान की प्रयोगशाला के लिए आवश्यक उपकरण मँगवाने हेतु उपकरण विक्रेता को लगभग 60 शब्दों में लिखिए आपके विद्यालय में ग्रीष्मावकाश के दौरान “्यक्तित्व विकास (पर्सनैल्टी डेवलपमेंट) शिविर' का आयोजन किया जा रहा है । छात्र कल्याण संगठन के सचिव होने के नाते कक्षा नवीं से बारहवीं तक के सभी छात्रों तक इस शिविर की जानकारी प्रदान करने हेतु लगभग शब्दों में एक सूचना पत्र तैयार कीजिए अथवा आपकी सोसायटी में गणतंत्र दिवस के अवसर सांस्कृतिक कार्यक्रम का आयोजन किया जा रहा है । रेजिडेंट वेलफेयर संगठन के सचिव होने के नाते सोसायटी निवासियों को इसकी जानकारी देने हेतु लगभग शब्दों में एक सूचना तैयार कीजिए । . (क) किसी दैनिक समाचार पत्र में प्रकाशित करने के लिए लगभग शब्दों में एक विज्ञापन का प्रारूप तैयार कीजिए जिसमें आवश्यक दस्तावेज यात्रा के समय मार्ग में खो जाने का उल्लेख हो। अथवा (ख) आर्थिक दृष्टि से कमजोर छात्रों को निःशुल्क शिक्षण सुविधा उपलब्ध कराने हेतु क.ख.ग. स",
