    "hi": "उत्तर वाले विकल्प चुनकर लिखिए : %व गरमियों के दिन छुट्टी और यात्रा” जाने के दिन होते हैं छुट्टी जाने! का यह अनुराग काफ़ी आधुनिक है, क्योंकि लोग “कर्मोन्मत्त' गए हैं और वे जो कुछ भी करते हैं या नहीं करते हैं, उनके लिए तनाव पैदा करता है । पहले छुट्टी' मूल रूप से धार्मिक दिनों के लिए इस्तेमाल होता था; आजकल इसका मतलब सामान्य दिनों के विपरीत आराम या विश्राम का कोई विशेष दिन है । लेकिन असली सवाल है कि छुट्टी जाने से पहले क्या आपका मन और शरीर नई जगह का आनंद लेने की स्थिति में है ? यात्रा की सारी तैयारी बाहरी होती है, लोग विश्राम की भाषा पूरी तरह भूल चुके हैं । आप कुछ नहीं करते, तो यह मत सोचना कि समय बर्बाद हो रहा है । कुछ न करने के दौरान आपकी ऊर्जा खुद को स्वस्थ करती है सतत काम करते रहने का जुनून ही आपको छुट्टी का आनंद नहीं लेने देता । आप जहाँ हैं, वहाँ मौजूद रहना सीखें, इसका अर्थ है अभी और यहीं होना । बाहरी दुनिया के बिना जीवित रहना सीखें । इसका स्पष्ट मतलब है, अपने साथ रहना शुरू करें, खुद को जानना सीखें । छुट्टी का मतलब यह कदापि नहीं कि आप सिर्फ कामकाज से दूरी बनाएँ, बल्कि अपने मन, उसके दबावों और उलझनों से भी दूरी बनाइए । ह॥नुू ? “छुट्टी जाने का यह अनुराग काफ़ी आधुनिक है' पंक्ति का आशय है",
