    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक उस आधारित दिए गए प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : ग्वालियर से बंबई की दूरी ने संसार को काफ़ी कुछ दिया है वर्सोवा में आज जहाँ मेरा घर है, पहले यहाँ दूर तक जंगल था । पेड़ थे, परिंदे थे और दूसरे जानवर थे अब यहाँ समंदर के किनारे लंबी चौड़ी बस्ती गई है । इस बस्ती ने न जाने कितने परिंदों चरिंदों से उनका घर छीन लिया है । इनमें से कुछ शहर छोड़कर चले गए हैं । जो नहीं जा सके हैं उन्होंने यहाँ वहाँ डेरा डाल लिया है । इनमें से दो कबूतरों ने मेरे फ्लैट के एक मचान में घोंसला बना लिया है । बच्चे अभी छोटे हैं उनके खिलाने पिलाने की जिम्मेदारी अभी बड़े कबूतरों की है । वे दिन में कई कई बार आते जाते हैं । और क्यों न आएँ जाएँ आखिर उनका भी घर है । लेकिन उनके आने जाने से हमें परेशानी भी होती हैं । वे कभी किसी चीज को गिराकर तोड़ देते हैं कभी मेरी लाइब्रेरी में घुसकर कबीर या मिर्ज़ा गालिब को सताने लगते हैं । इस रोज़ रोज़ की परेशानी से तंग आकर मेरी पत्नी ने उस जगह जहाँ उनका आशियाना था, एक जाली लगा दी है, उनके बच्चों को दूसरी जगह कर दिया है । उनके आने की खिड़की को भी बंद किया जाने लगा है । खिड़की के बाहर अब दोनों कबूतर रातभर खामोश और उदास बैठे रहते हैं",
