    "hi": "(क) (ख) न आपकी सोसायटी में बिजली के खंभों की मरम्मत के कारण बिजली की आपूर्ति दो घंटे के लिए बाधित रहेगी । इस संदर्भ में जानकारी देते हुए सोसायटी सचिव की ओर से लगभग शब्दों में एक सूचना तैयार कीजिए । अथवा आपके विद्यालय में जल प्रबंधन कार्यशाला का आयोजन किया जा रहा है । छात्र कल्याण संगठन के अध्यक्ष होने के नाते कक्षा छठी से बारहवीं तक सभी छात्रों को इसकी विस्तृत जानकारी देने हेतु एक सूचना पत्र लगभग शब्दों में तैयार कीजिए । प्रधानाचार्य, क.ख.ग. उच्चतर माध्यमिक विद्यालय की ओर से जिला के मुख्य चिकित्साधिकारी को लगभग शब्दों में एक लिखिए जिसमें विद्यालय के छात्रों के स्वास्थ्य परीक्षण का निवेदन किया गया हो । अथवा आप अपने विद्यालय के रसायन विज्ञान के अध्यापक हैं । रसायन विज्ञान की प्रयोगशाला के लिए आवश्यक उपकरण मँगवाने हेतु उपकरण विक्रेता को लगभग 60 शब्दों में लिखिए आपके पिताजी अपनी पुरानी स्कूटी बेचना चाहते हैं स्कूटी संबंधी समस्त जानकारी देते हुए किसी दैनिक समाचार पत्र में प्रकाशित करने के लिए लगभग शब्दों में एक विज्ञापन का प्रारूप तैयार कीजिए । अथवा आर्थिक दृष्टि से कमजोर छात्रों को निःशुल्क शिक्षण सुविधा उपलब्ध कराने हेतु क.ख.ग. स्कूल की ओर से एक आकर्षक विज्ञापन लगभग शब्दों में तैयार कीजिए । सच्चा मित्र' विषय लगभग शब्दों में एक लघुकथा लिखिए अथवा बड़ी के विवाह में सपरिवार सम्मिलित होने के लिए अपने मित्र को लगभग शब्दों में ई मेल द्वारा निमंत्रण भेजिए । है",
