    "hi": "निम्नलिखित पदयांश को ध्यानपूर्वक उस आधारित दिए गए प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : सुखिया संसार है, खायै अरू सोवै । दुखिया दास कबीर है, जागै अरू रोवै ।। बिरह भुवंगम तन बसे, मंत्र न लागै कोइ । राम बियोगी ना जिवै, जिवै तो बौरा होइ ।। पहले दोहे में 'सोना' और 'जागना' प्रतीकार्थ है ( ) अज्ञानता और ज्ञान का ( ) निष्क्रियता और सक्रियता का ( अचेतनता और चेतनता का ( ) निर्जीवता और सजीवता का ( ) कबीर दुखी हैं क्योंकि वे ( ) एकाकी जीवन व्यतीत कर रहे हैं । ( ) ईश्वर से वियोग के कारण व्यथित हैं । ( ) सांसारिक सुखों का भोग नहीं कर पा रहे हैं । ( ) ईश्वरीय से लोगों को परिचित नहीं करवा पा रहे हैं । मंत्र न लगना' का आशय है ( ) मंत्रों का निष्फल होना ( ) पूजा पाठ का काम न आना ( ) कोई उपाय काम न आना ( ) मंत्रोच्चार की विधि न जानना राम वियोगी व्यक्ति की तुलना किससे की गई है ? ( ) वीक्षिप्त व्यक्ति से ( ) विरह रूपी व्यक्ति से ( ) विष युक्त के तन से ( ) विरह रूपी से ग्रसित व्यक्ति से व कै ( ) निम्नलिखित कथन तथा कारण को ध्यानपूर्वक पढ़िए । उसके बाद दिए गए विकल्पों में से कोई एक सही विकल्प चुनकर लिखिए : कथन : सांसारिक मनुष्य सुख पूर्वक जीवन यापन कर रहे हैं । कारण : वह भौतिक सुखों को ही सच्चा सुख मानते हैं । ( ) कथन तथा कारण दोनों गलत हैं । ( ) कारण सही है, किंतु कथन गलत है । ( ) कथन सही है, लेकिन कारण कथन की गलत व्याख्या करता है । ( ) कथन तथा कारण दोनों सही हैं तथा कारण कथन की सही व्याख्या करता है । . काव्य खंड आधारित निम्नलिखित प्रश्नों के उत्तर देने के लिए उचित उत्तर वाले विकल्प का चयन कर लिखिए :",
