    "hi": "तोप' कविता के आधार 'तोप' और गौरैया' की प्रतीकात्मकता स्पष्ट करते हुए बताइए कि इस कविता के माध्यम से कवि क्या संदेश देना चाहता है ? ॥॥॥॥॥॥॥॥॥ हि ( ) 'टे न हेलमेल हाँ, बढ़े न भिन्नता कभी मनुष्यता कविता से ली गई इस पंक्ति के माध्यम से कवि ने जीवन रूपी मार्ग आगे बढ़ते समय क्या याद रखने को कहा है और क्यों ? (॥) कर चले हम फिदा' गीत में कवि देशवासियों से क्या अपेक्षाएँ रखता है? हम उसकी अपेक्षाओं किस रूप में खरा उतर रहे हैं ? सहित उत्तर दीजिए। पूरक पाठ्य पुस्तक आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं दो प्रश्नों के उत्तर लगभग शब्दों में दीजिए : ( ) हरिहर काका और टोपी शुक्ला दोनों ही भरे पूरे परिवार से संबंधित होते हुए भी अकेले थे। दोनों के अकेलेपन के कारणों की समीक्षा कीजिए । ( ) सपनों के से दिन पाठ में बच्चों को स्कूल जाना बिल्कुल भी पसंद नहीं था, क्यों? कारण सहित उत्तर स्पष्ट करते हुए बताइए कि स्कूल जाने के संबंध में आपका क्या अनुभव है? ( ) इफ्फ़न के पिता के तबादले के बाद टोपी शुक्ला का कोई और मित्र क्यों नहीं सका? इसका उसके बालमन क्या प्रभाव पड़ा ? निम्नलिखित में से किसी एक विषय संकेत बिंदुओं के आधार लगभग 100 शब्दों में अनुच्छेद लिखिए : (क) नाटक मंचन के दौरान मैं अपने संवाद भूल गया गई मेरी मनःस्थिति दर्शकों का उत्साहवर्धन सफलतापूर्वक नाटक की समाप्ति (ख) वर्षा की पहली फुहार",
