    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक पूछे गए प्रश्नों के उत्तर के लिए सर्वाधिक उचित विकल्प चुनकर लिखिए : [ राज कपूर ने एक अच्छे और सच्चे मित्र की हैसियत से शैलेंद्र को फ़िल्म की असफलता के खतरों से आगाह भी किया। वह तो एक आदर्शवादी भावुक कवि था, जिसे अपार संपत्ति और यश तक की इतनी कामना नहीं थी, जितनी आत्म संतुष्टि के सुख की अभिलाषा थी। तीसरी कसम कितनी ही महान् फ़िल्म क्यों न रही हो, लेकिन यह एक दुःखद है कि इसे प्रदर्शित करने के लिए बमुश्किल वितरक मिले। बावजूद इसके कि “तीसरी कसम में राज कपूर और वहीदा रहमान जैसे नामजद सितारे थे, शंकर जयकिशन का संगीत था, जिनकी लोकप्रियता उन दिनों सातवें आसमान थी और इसके गीत भी फ़िल्म के प्रदर्शन के पूर्व ही बेहद लोकप्रिय हो चुके थे, लेकिन इस फ़िल्म को खरीदने वाला कोई नहीं था। दरअसल इस फ़िल्म की संवेदना किसी दो से चार बनाने का गणित जानने वाले की समझ से परे थी। उसमें रची बसी करुणा तराज़ू तौली जा सकने वाली चीज़ नहीं थी। ( ) राज कपूर ने शैलेंद्र को किस बात से आगाह किया था ? ] ( ) फ़िल्म का किसी को समझ न आने वाली बात से। ( ) फ़िल्म से कोई आर्थिक लाभ न मिलने वाली बात से। ( ) फ़िल्म निर्माण में होने वाली परेशानियों से । ( ) फ़िल्म की संभावित असफलता के खतरों से । ( ) छैलेंद्र को किस प्रकार का व्यक्ति माना जा सकता है ? ] ( ) कुशल फ़िल्म निर्माता ( ) प्रसिद्ध गीतकार ( ) आदर्शवादी भावुक कवि ( ) आत्म संतुष्ट व्यक्ति ( ) तीसरी कसम फ़िल्म का दुःखद कया था ? ॥। ( ) फ़िल्म के लिए खरीददार का न मिलना। ( ) लोगों का फ़िल्म को न समझ पाना। ( ) फ़िल्म का रूपहले पर्दे न पहुँच पाना। ( ) फ़िल्म को प्रसिद्धि न मिल पाना। ॥॥॥॥॥॥॥॥॥॥ ॥ ए. . .",
