    "hi": "उत्तर वाले विकल्प चुनकर लिखिए : ठ जलवायु परिवर्तन के दौर में गरमी का बढ़ता प्रकोप अनेक चिताएँ उत्पन्न कर रहा है । भूमि के सभी क्षेत्र गरमी के प्रकोप से समान रूप से प्रभावित नहीं होते हैं । जहाँ अधिक हरियाली है, पेड़ हैं, वहाँ गरमी की मार अपेक्षाकृत कम है, जहाँ पूरा क्षेत्र सीमेंट कंक्रीट के निर्माणों और सड़कों से भरा पड़ा है, वहाँ गरमी अधिक होती है । प्रायः किसी भी शहर के लिए एक ही तापमान बताया जाता है, वास्तव में एक ही शहर के विभिन्न क्षेत्रों के तापमान में बहुत अंतर होता है । डिग्री सेल्सियस या उससे भी अधिक का अंतर एक ही महानगर या बड़े शहर के भीतर देखा जा सकता है । वृद्ध और पहले से कमज़ोर स्वास्थ्य के लोगों चरम गरमी के दिनों में विशेष ध्यान देने की जरूरत है । गरमी के प्रकोप से उन लोगों की स्थिति और बिगड़ सकती है, जो पहले से साँस व हृदय संबंधी समस्याओं से त्रस्त हैं । पर्यावरणविदों के अनुसार, शहरों में अधिक तापमान के कुछ प्रमुख कारण इस प्रकार हैं । आधुनिक शहरों का आकार प्रकार वायु के बहाव के हिसाब से ठीक नहीं है । गाँव में हवा रुकती नहीं है, लेकिन शहरों में ऊँची इमारतों की वजह से हवा रुकती है और बेचैनी बढ़ती है । शहर रेगिस्तान की तरह होने लगे हैं । कई जगहों किसी वनस्पति का नामोनिशान नहीं होता है, ऐसे इलाकों बारिश भी बेअसर होती है । वाष्पीकरण कम होता है और गरमी जाती है । शहरों में मानव जनित ऊष्मा भी बहुत गई है । पेट्रोलियम पदार्थों के अधिकतम उपयोग से भी शहरी तापमान रहा है । गरमी के प्रकोप को कम करने के लिए बसावट सुधारने से हरियाली बढ़ाने तक बहुत काम हैं, जो हमें करने चाहिए । स्थानीय प्रजाति के वृक्षों की संख्या बढ़ाने तथा परंपरागत जलस्रोतों की रक्षा ध्यान देना चाहिए",
