    "hi": "निम्नलिखित में से किसी एक विषय दिए गए संकेत बिंदुओं के आधार लगभग 100 शब्दों में अनुच्छेद लिखिए : (क) माँ पिताजी की शादी की बीसवीं सालगिरह सगे संबंधियों और मित्रों को निमंत्रण « कार्यक्रम की तैयारी रंगारंग कार्यक्रम और माँ पिताजी की प्रसन्नता (ख) क्यों प्रिय है, मुझे मेरा देश ? भौगोलिक विविधता « प्राकृतिक सुंदरता विविधता में एकता (ग) स्वरोज़गार : आत्मनिर्भरता की सीढ़ी « स्वरोज़गार का अर्थ समय की माँग युवा प्रतिभाओं को निखरने का मौका . . हर न नि आप क.ख.ग. कॉलोनी के निवासी हैं । आपके क्षेत्र में गत कई दिनों से बंदरों का प्रकोप गया है । इस समस्या के शीघ्रातिशीघ्र समाधान के लिए नगर निगम अधिकारी को लगभग 60 शब्दों में लिखिए । अथवा आपके घर में पिछले कई दिनों से गंदा और बदबूदार पानी आ रहा है । इस समस्या के शीघ्रातिशीघ्र समाधान के लिए नगर निगमाधिकारी को लगभग व शब्दों में लिखिए । आपके विद्यालय में हिन्दी दिवस के अवसर हिन्दी सप्ताह आयोजित किया जा रहा है जिसमें हिन्दी भाषा से संबंधित विभिन्न गतिविधियाँ यथा कवि गोष्ठी, नाट्य मंचन, वाद विवाद आदि का आयोजन किया जाएगा । विद्यालय के सांस्कृतिक समिति के अध्यक्ष की ओर से इसकी जानकारी देते हुए लगभग शब्दों में एक सूचना तैयार कीजिए । अथवा विद्यालय के प्रधानाचार्य की ओर से आपदा प्रबंधनं आयोजित होने वाली कार्यशाला की जानकारी देते हुए लगभग शब्दों में एक सूचना तैयार कीजिए । आपकी बड़ी बहुत ही स्वादिष्ट केक और पेस्ट्री बनाती हैं उनकी बिक्री के प्रचार प्रसार हेतु लगभग शब्दों में एक आकर्षक विज्ञापन तैयार कीजिए । अथवा आपके पिताजी अपना दो कमरों वाला फ्लैट किराए देना चाहते हैं",
