    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक पूछे गए प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : ] उस छोटी लड़की का जीवन निराशा से भरा हुआ था । माता पिता भी लाचार थे । वे चाहकर भी अपनी बेटी के लिए कुछ नहीं कर पाते थे से ही वह चलने फिरने में अक्षम थी । बैसाखी के बिना उसका एक कदम भी चलना मुश्किल था । एक शाम वह लड़की अपने घर के पास ही पार्क में चुपचाप बैठी थी । उसकी नजर की उस मूर्ति पड़ी, जिसमें एक युवती दौड़ने की मुद्रा में खड़ी थी । वह मूर्ति इतनी जीवंत थी, गोया अभी दौड़ पड़ेगी । लड़की मूर्ति को देखकर सोचने लगी, क्या ऐसा नहीं हो सकता कि मैं भी उस मूर्ति की मुद्रा में दौड़ पाऊँ ? मुझे कोशिश तो करनी चाहिए । हर न नि अगली सुबह वह उस प्रतिमा के पास देर तक उसी मुद्रा में टिकने की कोशिश करती, बार बार गिरती, किंतु हरेक विफलता के साथ उसका हौसला दोगुना हो जाता । उसे घोर पीड़ा होती थी, पैर भी लहलुहान हो जाते थे, किंतु उसने प्रयास करना नहीं छोड़ा और एक दिन वह अपने पैरों सीधी खड़ी हो गई । उस लड़की की अथक कोशिश में मानव जीवन के लिए एक गहरा संदेश छिपा है हमारी सोच से ही हमारे जीवन और संस्कारों का निर्माण होता है । सोच सकारात्मक हो, उसके प्रति दृढ़ रहा जाए, तो हम दुनिया की हर तस्वीर को सकते हैं । स्वामी विवेकानंद कहा करते थे, हम सभी वही होते हैं, जो हमारे विचार हमें बनाते हैं । इसलिए आप जो सोचते हैं उसके बारे में ध्यान रखना चाहिए । हमारे विचार दूर तक जाते हैं । हम अपने जीवन में हज़ारों बार असफल हो सकते हैं, लेकिन ख़ुद को कभी भी हारा हुआ नहीं समझना चाहिए । हालाँकि विफलता के बाद सोच को स्थिर रखना आसान नहीं होता । इसके लिए मस्तिष्क के अनुकूलन की जरूरत होती है । इसलिए नकारात्मक सोच से हमें सावधान रहने की जरूरत है क्योंकि गिरना तो जीवन की कुदरती प्रक्रिया है । छोटी लड़की का जीवन निराशापूर्ण क्यों था ?",
