    "hi": "खंड आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं दो प्रश्नों के उत्तर लगभग 60 शब्दों में लिखिए : (क) “ चा नो यू? विधि से क्या तात्पर्य है ? इसका करते हुए इसके लाभ 'झेन की देन” पाठ के आधार पर लिखिए। (ख) '«डायरी का एक पन्ना” पाठ के आधार पर सिद्ध कीजिए कि एक संगठित समाज कृतसंकल्प हो तो वह कुछ भी कर सकता है। (ग) “ततारा एक नेक और मददगार व्यक्ति था? कथन का क्या आधार है ? “तताँरा वामीरो कथा' के संदर्भ में स्पष्ट कीजिए । . काव्य खंड आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं दो प्रश्नों के उत्तर लगभग 60 शब्दों में लिखिए : (क) कबीर की “साखियों” की भाषा टिप्पणी कीजिए। (ख) प्रदेश में पावस” कविता में कवि ने ऊँचे ऊँचे वृक्षों की किन विशेषताओं का किया है ? अपने शब्दों में लिखिए । (ग) “आत्मत्राणः शीर्षक कविता में कवि ने ईश्वर से क्या प्रार्थना की है और क्यों ?",
