    "hi": "पूरक पाठ्य पुस्तक आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं दो प्रश्नों के उत्तर लगभग 60 शब्दों में लिखिए : (क) हरिहर काका की अपने परिवार में जो स्थिति है वह आज के वरिष्ठ नागरिकों की स्थिति से कैसे भिन्न अथवा समान है ? इस विषय में अपने विचार स्पष्ट कीजिए । (ख) टोपी के अपने मित्र की दादी के साथ स्नेहपूर्ण सम्बन्ध किस पर प्रकाश डालते हैं ? “टोपी शुक्ला? कहानी के आधार लिखिए। (ग) “सपनों के से दिन! पाठ के आधार पर लेखक ने कहानी के प्रारम्भ में लिखा है “मेरे साथ खेलने वाले बच्चों का हाल एक सा होता । नंगे पाँव, फटी मैली सी कच्छी और टूटे बटनों वाले कुर्ते” ये बच्चों की किस स्थिति को प्रकट कर रहे हैं ? . ण् निम्नलिखित में से किसी एक विषय दिए गए संकेत बिन्दुओं के आधार लगभग शब्दों में एक अनुच्छेद लिखिए : (क) नारी सुरक्षा देश की रक्षा संकेत बिंदु (ख) (ग) (क) (ख) नारी समाज का महत्त्वपूर्ण अंग नारी विकास, परिवार का विकास नारी विकास में बाधाएँ योग और वसुधैव कुटुम्बकम् संकेत बिंदु योग और वसुधैव कुटुम्बकम् का अर्थ दोनों एक दूसरे के पूरक भूमंडलीकरण का महत्त्वपूर्ण अंग मोबाइल इल खेले जाने न वाले ल खेल और मानव संकेत बिंदु आउटडोर खेलों में कमी आँखों और शरीर के अन्य अंग प्रभावित सोच में संकीर्णता “योग दिवस” आपकी “आवासीय कल्याण समिति! सामूहिक योग का आयोजन करने जा रही है। इससे संबंधित सम्पूर्ण जानकारी देते हुए एक सूचना लगभग शब्दों में तैयार कीजिए। अथवा आधार कार्ड में सुधार और बदलाव करने के लिए “सरिता विहार पॉकेट बी” में एक कैम्प का आयोजन सरकारी बैंक की शाखा द्वारा किया जा रहा है। क्षेत्रवासियों को इसकी जानकारी देन",
