    "hi": "पाठों आधारित निम्नलिखित तीन प्रश्नों में से किन््हीं ढ्गो प्रश्नों के उत्तर लगभग 60 शब्दों में लिखिए : (क) “अब कहाँ दूसरों के दुख से दुखी होने वाले पाठ में लेखक की माँ उन्हें प्रकृति का ख्याल रखने के बारे में क्या क्या बताती थीं ? इनके माध्यम से वह लेखक में किन जीवन मूल्यों का विकास करना चाहती थी ? (ख) तताँरा वामीरों कथा का नायक अपने क्रोध का शमन करने के लिए तलवार को धरती में घोंप उसे दूर तक ले जाता है । आप अपने निजी जीवन में क्रोध का शमन करने के लिए क्या क्या करते हैं ? (ग) तीसरी कसम के शिल्पकार छजैलेंद्र\"ं पाठ से लिए गए कथन (ऐसा नहीं कि छैलेंद्र बीस सालों तक फ़िल्म इंडस्ट्री में रहते हुए भी वहाँ के तौर तरीकों से नावाकिफ़ थे, परंतु उनमें उलझकर वे अपनी आदमियत नहीं खो सके थे ।” के संदर्भ में शैलेंद्र की विशेषताएँ लिखिए",
