    "hi": "पठित गद्यांश आधारित निम्नलिखित प्रश्नों के उत्तर के लिए सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : ] बड़े बाज़ार के प्राय: मकानों राष्ट्रीय झंडा फहरा रहा था और कई मकान तो ऐसे सजाए गए थे कि ऐसा मालूम होता था कि मानो स्वतंत्रता मिल गई हो । कलकत्ते के प्रत्येक भाग में ही झंडे लगाए गए थे । जिस रास्ते से मनुष्य जाते थे, उसी रास्ते में उत्साह और नवीनता मालूम होती थी । लोगों का कहना था कि ऐसी सजावट पहले नहीं हुई । पुलिस भी अपनी पूरी ताकत से शहर में देकर प्रदर्शन कर रही थी । मोटर लारियों में गोरखे तथा सारजेंट प्रत्येक मोड़ तैनात थे । कितनी ही लारियाँ शहर में घुमाई जा रही थीं । घुड़सवारों का प्रबंध था । कहीं भी ट्रैफिक पुलिस नहीं थी, सारी पुलिस को इसी काम में लगाया गया था । बड़े बड़े पार्कों तथा मैदानों को पुलिस ने सवेरे से ही घेर लिया था । मोनुमेंट के नीचे जहाँ शाम को सभा होने वाली थी उस जगह को तो भोर में छह बजे से ही पुलिस ने बड़ी संख्या में घेर लिया था । घुड़सवारों का प्रबंध किसकी ओर से किया गया था ? ( ) पुलिस प्रशासन ( ) कांग्रेस कौंसिल ( ) स्थानीय समिति ( ) केन्द्र सरकार ( ) बड़े बाज़ार के मकानों को सजाने और उन राष्ट्रीय फहराने का क्या कारण था? ( ) स्वतंत्रता प्राप्ति की खुशी मनाना ( ) स्वतंत्रता दिवस की वर्षगाँठ मनाना ( ) लोगों में उत्साह और नवीनता का संचार करना ( ) लोगों में देशभक्ति की भावना का संचार करना शहर में कहीं भी ट्रैफ़िक पुलिस क्यों नहीं थी ? ( ). ट्रैफ़िक पुलिस के काम में लगी थी । ( ) उस दिन शहर में कोई ट्रैफ़िक नहीं था । ( ट्रैफ़िक पुलिस आज़ादी का उत्सव मना रही थी । ( ) ट्रैफ़िक पुलिस को निरस्त कर दिया गया था",
