    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक पूछे गए प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : पृथ्वी लगातार ख़तरे मँडराते रहते हैं हर साल हज़ारों की संख्या में उल्का पिंड पृथ्वी की ओर आते हैं । और इनसे कभी कभी वैज्ञानिकों को भी ख़तरा महसूस होने लगता है । उल्का से पैदा ख़तरे से निबटने के लिए वैज्ञानिक तरीके भी खोजते रहे हैं नासा की सोच रही है कि क्या परमाणु हथियारों के दम किसी ख़तरनाक उल्का पिंड को पृथ्वी से टकराने से पहले ही किया जा सकता है ? कया उल्का पिंड की दिशा को रॉकेट बूस्टर इत्यादि से मोड़ा जा सकता है ? अभी इन दोनों ही उपायों ज्यादा काम नहीं हुआ है । लेकिन वैज्ञानिकों को यह भी लगता है कि कभी कोई ज्यादा ही ख़तरनाक उल्का पिंड पृथ्वी से टकराया तो क्या होगा ? पृथ्वी के इंसान अगर ख़त्म हो गए तो क्या होगा ? एक समाधान एक अमेरिकी उद्यमी की ओर से आया है, जो काफी रोचक है । बेन हल्डमैन नामक उद्यमी “लाइफशिप” नामक एक स्टार्टअप के संस्थापक हैं, जिनका सिर्फ एक ही अभियान है मानव बीज बैंक बनाना । दूसरे शब्दों में कहें तो इस बैंक में मानव डीएनए को संरक्षित किया जाएगा । यह बैंक चाँद स्थापित होगा । अगर इस धरती इंसान ख़त्म हो गए, तो मानव सभ्यता को फिर शुरू करने में यह बैंक सहायक होगा । मानव बीज बैंक में किसे संरक्षित किए जाने की योजना है ?",
