    "hi": "तोप' कविता के आधार 'तोप' और गौरैया' की प्रतीकात्मकता स्पष्ट करते हुए बताइए कि इस कविता के माध्यम से कवि क्या संदेश देना चाहता है ? ( ) 'टे न हेलमेल हाँ, बढ़े न भिन्नता कभी मनुष्यता कविता से ली गई इस पंक्ति के माध्यम से कवि ने जीवन रूपी मार्ग आगे बढ़ते समय क्या याद रखने को कहा है और क्यों ? (॥) कर चले हम फिदा' गीत में कवि देशवासियों से क्या अपेक्षाएँ रखता है? हम उसकी अपेक्षाओं किस रूप में खरा उतर रहे हैं ? सहित उत्तर दीजिए । खंड आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं दो प्रश्नों के उत्तर लगभग शब्दों में दीजिए ; ( ) बड़े भाई साहब' कहानी का बड़ा भाई शिक्षा को रटंत ज्ञान और 'बे सिर पैर की बातें! मानता है जिनका व्यावहारिक जीवन में कोई अर्थ नहीं ? इस संदर्भ में आपके क्या विचार हैं ? तर्कपूर्ण उत्तर दीजिए। ( ) डायरी का एक पन्ना पाठ के आधार पर लिखिए कि अंग्रेज सरकार ने कलकत्तावासियों द्वारा मोनूमेंट पार्क में आयोजित सभा को रोकने के लिए क्या क्या प्रयास किए? (॥) कारतूस एकांकी के आधार स्पष्ट कीजिए कि सआदत अली वजीर अली का सगा चाचा होते हुए भी उससे क्यों करता था ? ॥॥॥॥॥॥॥॥॥ पूरक पाठ्य पुस्तक आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं दो प्रश्नों के उत्तर लगभग शब्दों में दीजिए : ( ) हरिहर काका और टोपी शुक्ला दोनों ही भरे पूरे परिवार से संबंधित होते हुए भी अकेले थे। दोनों के अकेलेपन के कारणों की समीक्षा कीजिए । ( ) सपनों के से दिन पाठ में बच्चों को स्कूल जाना बिल्कुल भी पसंद नहीं था, क्यों? कारण सहित उत्तर स्पष्ट करते हुए बताइए कि स्कूल जाने के संबंध में आपका क्या अनुभव है? ( ) इफ्फ़न के पिता के तबादले के बाद टोपी",
