    "hi": "उत्तर वाले विकल्प चुनकर लिखिए : [ कृषि में हरी खाद उस सहायक को कहते हैं जिसकी खेती मुख्यतः भूमि में पोषक तत्त्वों को बढ़ाने तथा उसमें जैविक पदार्थों की पूर्ति करने के उद्देश्य से की जाती है। प्रायः इस तरह की को हरित स्थिति में हल चलाकर मिट्टी में मिला दिया जाता है। हरी खाद से भूमि की उपजाऊ शक्ति बढ़ती है और भूमि की रक्षा होती है। मृदा के लगातार उपयोग से उसमें उपस्थित पौधे की बढ़वार के लिए आवश्यक तत्त्व होते जाते हैं। इनकी क्षतिपूर्ति के लिए और मिट्टी की उपजाऊ शक्ति को बनाए रखने के लिए हरी खाद एक उत्तम विकल्प है। बिना गले सड़े हरे पौधे (फसलों अथवा उनके भाग) को मिट्टी की नत्रजन या जीवांश की मात्रा बढ़ाने के लिए खेत में दबाया जाता है तो इस क्रिया को हरी खाद देना कहते हैं। हरी खाद के उपयोग से न सिर्फ जीवांश भूमि में उपलब्ध होता है बल्कि मृदा की भौतिक, रासायनिक एवं जैविक दशा में भी सुधार होता है। वातावरण तथा भूमि प्रदूषण की समस्या को समाप्त किया जा सकता है। लागत घटने से किसानों की आर्थिक स्थिति बेहतर होती है, भूमि में सूक्ष्म तत्त्तों की आपूर्ति होती है साथ ही साथ मृदा की उर्वरा शक्ति भी बेहतर हो जाती है",
