    "en": "",
    "hi": "(क) गणतंत्र दिवस' के अवसर आपकी सोसायटी के पार्क में ध्वजारोहण और खेल कूद प्रतियोगिता का आयोजन किया जा रहा है। सोसायटी सचिव की ओर से इस जानकारी को लोगों तक पहुँचाने के लिए लगभग शब्दों में एक सूचना तैयार कीजिए। अथवा ॥॥॥॥॥ (ख) आप विद्यालय के हैड बॉय हैड गर्ल, देव देविका हैं। बाल दिवस के अवसर विद्यालय में एक विज्ञान मेला आयोजित किया जा रहा है, जिसमें छात्रों द्वारा तैयार मॉडल और परियोजना कार्य प्रदर्शित किए जाएँगे। सर्वश्रेष्ठ मॉडल और परियोजना कार्य को प्रथम, द्वितीय और तृतीय पुरस्कार भी दिया जाएगा। इस मेले से संबंधित जानकारी देते हुए एक सूचना लगभग शब्दों में तैयार कीजिए । (क) आपके पिताजी अपनी पुरानी कार बेचना चाहते हैं। कार संबंधी सम्पूर्ण जानकारी देते हुए लगभग शब्दों में एक आकर्षक विज्ञापन तैयार कीजिए । अथवा (ख) आपके क्षेत्र में अ.ब.स. द्वारा निःशुल्क दंत जाँच शिविर का आयोजन किया जा रहा है जिसमें योग्य और अनुभवी चिकित्सकों द्वारा दाँतों की जाँच की जाएगी। अ.ब.स. की ओर से इसके प्रचार हेतु एक विज्ञापन लगभग शब्दों में तैयार कीजिए। (क) रमेश बाबू ने बड़े ही मन से पुत्र के लिए मोबाइल खरीदा।' पंक्ति को आधार बनाकर लगभग व शब्दों में एक लघु कथा लिखिए। अथवा (ख) मौसम विभाग द्वारा भारी बारिश की चेतावनी जारी किए जाने के कारण जिला प्रशासन ने दो दिन के लिए शिक्षण संस्थानों को बंद रखने का निर्देश दिया है। स्कूल प्रधानाचार्य की ओर से लगभग शब्दों में, अभिभावकों तक इस जानकारी को पहुँचाने के लिए विद्यालय की वेबसाइट डालने के लिए एक ई मेल तैयार कीजिए। ॥॥॥॥॥॥॥॥॥ क्",
