    "hi": "(क) आपका नाम मुदित मुदिता है। प्रतियोगी परीक्षाओं में प्रवेश हेतु प्रदेश सरकार द्वारा आर्थिक दृष्टि से कमजोर, प्रतिभाशाली छात्रों के लिए निःशुल्क शिक्षण की जो व्यवस्था की गई है, उसकी सराहना करते हुए किसी दैनिक हिन्दी समाचार पत्र के संपादक को लगभग व शब्दों में एक लिखिए। अथवा (ख) आज़ादी के अमृत महोत्सव आयोजित की जाने वाली सांस्कृतिक गतिविधियों के अभ्यास हेतु सांस्कृतिक कला सचिव की ओर से स्कूल के प्रधानाचार्य को लगभग व शब्दों में एक लिखिए जिसमें प्रार्थना सभा के दौरान अभ्यास की अनुमति माँगी गई हो",
