    "hi": "पूरक पाठ्य पुस्तक आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं क्गो प्रश्नों के उत्तर लगभग शब्दों में दीजिए : (क) 'हरिहर काका कहानी के आधार लिखिए कि कहानी के अंत में हरिहर काका की सुरक्षा में राइफलधारी पुलिस के चार जवान क्यों नियुक्त किए गए । हरिहर काका की वास्तविक सुरक्षा किसके द्वारा और कैसे की जा रही थी ? (ख) सपनों के से दिन पाठ में बच्चों को अनुशासन में रखने के लिए माता पिता, भाई बहनों और अध्यापकों द्वारा मार पीट करने का जिक्र आया है । वर्तमान समय में इसमें क्या परिवर्तन आया है ? आपकी दृष्टि में कौन सा तरीका अधिक बेहतर है ? (ग) टोपी शुक्ला' कहानी के आधार लिखिए कि कहानी का प्रमुख पात्र टोपी अपने बड़े भाई मुन्नी बाबू से क्यों चिढ़ता था । टोपी के साथ मुन्नी बाबू द्वारा किए गए व्यवहार को आप कितना उचित मानते हैं ? सहित उत्तर दीजिए",
