    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक पूछे गए प्रश्नों के उत्तर के लिए सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : महज़ इम्तिहान पास कर लेना कोई चीज़ नहीं, असल चीज़ है बुद्धि का विकास । जो कुछ पढ़ो, उसका अभिप्राय समझो । रावण भूमंडल का स्वामी था । ऐसे राजाओं को चक्रवर्ती कहते हैं । आजकल अंग्रेज़ों के राज्य का विस्तार बहुत बढ़ा हुआ है, इन्हें चक्रवर्ती नहीं कह सकते । संसार में अनेक राष्ट्र अंग्रेज़ों का आधिपत्य स्वीकार नहीं करते, बिलकुल स्वाधीन हैं । रावण चक्रवर्ती राजा था, संसार के सभी महीप उसे कर देते थे । बड़े बड़े देवता उसकी गुलामी करते थे आग और पानी के देवता भी उसके दास थे, मगर उसका अंत क्या हुआ ? घमंड ने उसका नामोनिशान तक मिटा दिया, कोई उसे एक चुह्लू पानी देने वाला भी न बचा । आदमी और जो कुकर्म चाहे करे, अभिमान न करे, इतराये नहीं । अभिमान किया और दीन दुनिया दोनों से गया । . जो कुछ पढ़ो, उसका अभिप्राय समझो । पंक्ति का आशय है : ( ) पुस्तकीय ज्ञान का अक्षरश: अर्थ समझना ( ) पुस्तकीय ज्ञान से बुद्धि का विकास करना ( ) पुस्तकीय ज्ञान से परीक्षा पास करना ( ) पुस्तकीय ज्ञान से अच्छे अंक लाना ( ) अंग्रेज़ों को रावण की तरह चक्रवर्ती सम्राट क्यों नहीं कहा जा सकता ? ( ) क्योंकि सभी देवता उनके दास नहीं थे ( ) क्योंकि सभी देवता उन्हें कर नहीं देते ( ) क्योंकि समस्त भूमंडल उनका स्वामित्व नहीं था ( ) क्योंकि वे रावण की तरह शक्तिशाली नहीं थे ( ) रावण के अंत का क्या कारण था ? ( ) अपनी शक्ति घमंड करना ( ) सभी देवताओं को दास बनाना ( ) सभी राजाओं से कर लेना ( ) सीता का हरण करना बड़े भाई ने लेखक को रावण का उदाहरण क्यों दिया ? ( ). रावण के अंत से",
