    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक इस आधारित प्रश्नों के लिए सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : शोर से होने वाली बहरेपन की बीमारी एक गंभीर स्वास्थ्यगत समस्या है । तेज आवाज हमारी श्रवण कोशिकाओं बहुत दबाव डालती है, जिससे वे स्थायी रूप से चोटिल हो सकती हैं । यदि सुनने की क्षमता एकबार चली गई तो उसे पुनः पाना नामुमकिन है । विश्व स्वास्थ्य संगठन की “वर्ल्ड हीयरिंग रिपोर्ट' के मुताबिक विश्व की . अरब आबादी बहरेपन के साथ जी रही है । ध्वनि प्रदूषण दरअसल ऐसे अवांछित विद्युत चुंबकीय संकेत है, जो इंसान को कई रूपों में नुकसान पहुँचाते हैं इसीलिए, शोर प्रेरित बहरेपन फौरन ध्यान देने की जरूरत है । वैश्विक अध्ययन बताते हैं कि निर्माण कार्य, औद्योगिक कामकाज, जहाज बनाने या मरम्मत करने संबंधी काम, अग्निशमन, नागरिक उड़डयन आदि सेवाओं में लगे श्रमिकों में शोर प्रेरित बहरेपन का खतरा अधिक होता है । आकलन है कि फीसदी नौजवान संगीत कार्यक्रमों, खेल आयोजनों और दैनिक कामकाज में होने वाले शोर से बहरेपन का शिकार होते हैं शोर प्रेरित बहरेपन की समस्या विकासशील देशों में ज्यादा है, जहाँ तीव्र औद्योगीकरण, अनौपचारिक क्षेत्र के विस्तार और सुरक्षात्मक व शोर नियंत्रणरोधी उपायों की कमी से लोग चौतरफा शोर शराबे में दिन बिताने को अभिशप्त हैं हमें यह समझना ही होगा कि श्रवण शक्ति का हास न सिर्फ इंसान को प्रभावित करता है, बल्कि समाज भी नकारात्मक असर डालता है",
