    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक इस आधारित प्रश्नों के लिए सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : व \" कभी कभी सहज से तेज़ गति में परिवर्तित होते क्रोध को समय रहते नियंत्रित नहीं किया गया तो उसके परिणाम अत्यंत घातक और पश्चात्ताप के भाव जगाने वाले हो सकते हैं । कैलिफोर्निया स्टेट यूनिवर्सिटी के मनोविश्लेषक टॉम जी. स्टीवेन्स ने अपनी किताब 'ओवरकम एंगर ऐंड एग्रेसन' में स्पष्ट किया है कि क्रोध नियंत्रण का एक प्रमुख तरीका यह है कि स्थिति को अपने नहीं, दूसरों के नजरिये से देखें । दूसरों को उन स्थितियों प्रकाश डालने के लिए प्रोत्साहित करें, क्षमा करना सीखें, बीते को बिसारने की आदत विकसित करें और किसी को चोट पहुँचाने के बजाय प्रशंसा से उसका मूल्यांकन करें । याद रखें, क्रोध नियंत्रण से आप स्वयं को शक्तिशाली बनाते हैं । इससे आपकी खुशहाली और स्मृतियों का विस्तार होता है । यूनिवर्सिटी ऑफ सिनसिनाटी के वैज्ञानिकों ने अपनी किताब साइंस ऑफ मेंटल इलनेस में इन कमजोरियों प्रकाश डालते हुए गुस्से को काबू में रखने के कारगर सूत्र दिए हैं । क्रोध नियंत्रण से हम अपना ही नहीं, दूसरों के उजड़ते संसार को फिर से आबाद कर सकते हैं क्योंकि शांत मन सृजन में समर्थ होता है । हमारे सृजनात्मक होने से ही मानवता का हित सध सकता है । तो भी क्रोध आए, इन उपायों को आजमाएँ । जीवन में बिखरी हुई चीजों को सँवारने की ओर कदम खुद चलेंगे",
