    "hi": "व सदियों पूर्व, लिटिल अंदमान और कार निकोबार आपस में जुड़े हुए थे वहाँ एक सुंदर सा गाँव था । पास में एक सुंदर और शक्तिशाली युवक रहा करता था । उसका नाम था तताँरा । निकोबारी उसे बेहद प्रेम करते थे । तताँग एक नेक और मददगार व्यक्ति था । सदैव दूसरों की सहायता के लिए रहता । अपने गाँववालों को ही नहीं, अपितु समूचे द्वीपवासियों की सेवा करना अपना कर्तव्य समझता था । उसके इस त्याग की वजह से वह चर्चित था । सभी उसका आदर करते । मुसीबत में उसे स्मरण करते और वह भागा भागा वहाँ पहुँच जाता । दूसरे गाँवों में भी पर्व त्योहारों के समय उसे विशेष रूप से आमंत्रित किया जाता । उसका व्यक्तित्व तो आकर्षक था ही, साथ ही आत्मीय स्वभाव की वजह से लोग उसके करीब रहना चाहते । पारंपरिक पोशाक के साथ वह अपनी कमर में सदैव एक लकड़ी की तलवार बाँधे रहता । लोगों का ए ] . . . घुड मत था, बावजूद लकड़ी की होने पर, उस तलवार में अद्भुत दैवीय शक्ति थी । तताँरा अपनी तलवार को कभी अलग न होने देता । उसका दूसरों के सामने उपयोग भी न करता । किंतु उसके चर्चित साहसिक कारनामों के कारण लोग बाग तलवार में अद्भुत शक्ति का होना मानते थे । तताँगा की तलवार एक विलक्षण रहस्य थी",
