    "hi": "इससे लाभ < ?स् ( ) आप विद्यालय के प्रमुख छात्र नलिन हैं । आपके विद्यालय में कैंटीन की समुचित व्यवस्था नहीं है । विद्यालय की प्रधानाचार्या से इस समस्या का समाधान करने की प्रार्थना करते हुए लगभग व शब्दों में लिखिए । अथवा ( ) देश के विभिन्न राज्यों में बढ़ते प्रदूषण चिंता प्रकट करते हुए हिन्दी दैनिक समाचार के संपादक को लगभग 60 शब्दों में लिखिए । निम्नलिखित विषयों में से किसी एक विषय लगभग शब्दों में लघधुकथा लिखिए: ( ) एकता में अथवा ( ) सत्संग का प्रभाव (क) ( ) (ख) ( ) (क) ( ) (ख) ( ) पिछली कक्षा की अपनी पुरानी पुस्तकें गरीब विद्यार्थियों में निःशुल्क वितरण करने हेतु लगभग शब्दों में एक विज्ञापन तैयार कीजिए । अथवा विद्यालय में आयोजित होने वाले पुस्तक मेले का प्रचार प्रसार करने हेतु लगभग शब्दों में एक विज्ञापन तैयार कीजिए । आप अपनी पुरानी साइकिल बेचना चाहते हैं इसकी जानकारी देते हुए लगभग शब्दों में एक विज्ञापन तैयार कीजिए अथवा आपके पिता श्रृंगार वस्तुओं के विक्रेता हैं । कोरोना महामारी के कारण उनके कारोबार में मंदी आ गई । उनकी दुकान में बिक्री बढ़ाने के लिए लगभग शब्दों में एक विज्ञापन तैयार कीजिए । आप विद्यालय के प्रमुख छात्र, मानव हैं आपके विद्यालय में आपदा प्रबंधन की ओर से एक कार्यशाला का आयोजन होने वाला है । छठी से लेकर बारहवीं कक्षा तक के विद्यार्थियों को सूचित करने हेतु शब्दों में एक सूचना तैयार कीजिए अथवा विद्यालय की सांस्कृतिक सभा के सचिव होने के नाते गणतंत्र दिवस' के अवसर आयोजित कार्यक्रम के विषय में विद्यार्थियों को सूचित करने के लिए लगभग शब्दों में एक सूचना तैयार कीजिए सागर अपार्टमेन्ट के सच",
