    "en": "",
    "hi": "खंड आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं द्वो प्रश्नों के उत्तर लगभग शब्दों में दीजिए : (क) डायरी का पन्ना पाठ में जनता आज़ादी का मनाने के लिए अत्यन्त उत्साहित थी, पुलिस इस को मनाने के लिए जनता को हतोत्साहित कर रही थी । पुलिस के लिए यह आयोजन रोकना आवश्यक था, क्यों ? संगत उत्तर दीजिए । (ख) तीसरी कसम फ़िल्म में ऐसा क्या था कि लोगों के लिए आज भी यह एक यादगार फ़िल्म है ? (ग) लोक कथाओं में राजा की जान तोते में बसना जैसी बातों की चर्चा मिलती है । तताँरा बामीरों कथा पाठ में तताँरा द्वारा लकड़ी की तलवार से पृथ्वी को दो भागों में बाँटगा आपको कितना विश्वसनीय लगा, लिखिए",
