    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक पूछे गए प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : एक समय की बात है । गुरु गोबिद सिंह के के लिए उनका एक वैद्य शिष्य आनंदपुर साहिब गया हुआ था । वैद्य लौटने लगे तो गुरु जी ने कहा, “जाओ और ज़रूरतमंद लोगों की सेवा करो ।” गाँव लौटने के बाद वह रोगियों की सेवा में जुट गया । वैद्य ने अब रोगियों की सेवा को अपना मान लिया । तन मन से रोगियों की सेवा में लग गए । वैद्य की सेवा की चर्चा पूरे शहर में फैल गई । एक बार गुरु गोबिंद सिंह स्वयं उनके घर आए । वैद्य की खुशी का ठिकाना न रहा । लेकिन गुरु जी ने कहा कि उन्हें आगे जाना है । अतः वह कुछ देर ही ठहरेंगे । गुरुजी वैद्य का हाल चाल पूछ रहे थे कि इतने में एक व्यक्ति भागता हुआ आया और बोला, “वैद्य जी, मेरी पत्नी की तबीयत बहुत खराब है । जल्दी चलिए नहीं तो बहुत देर हो जाएगी ।” वैद्य असमंजस में गए । पहली बार गुरुजी उनके घर आए हैं, उन्हें छोड़कर कैसे जाएँ ? दूसरी रोगी की हालत बहुत खराब है । वैद्य ने तुरंत निर्णय लिया और को प्रधानता दी । गुरु के चरण स्पर्श कर वह तुरन्त इलाज के लिए निकल पड़े । तक लगभग दो ढाई घंटे की देखभाल के बाद रोगी की हालत में सुधार हुआ । रोगी के यहाँ से वैद्य निकले और तेज़ी से घर की चल दिए । वैद्य ने सोचा कि गुरु जी के पास समय नहीं था, अब तक तो वह चले गए होंगे । फिर भी भागते भागते अपने घर पहुँचे । वहाँ पहुँचकर उन्होंने जो कुछ देखा, उससे हैरान रह गए । गुरु जी गए नहीं थे, उनकी प्रतीक्षा में बैठे हुए थे । वैद्य उनके चरणों गिर पड़े । गुरु गोबिंद सिंह ने उन्हें गले से लगा लिया और कहा, तुम मेरे सच्चे शिष्य हो । सबसे बड़ी सेवा ज़रूरतमंदों की मदद करना है ।” गुरु जी से मिलने के बाद वैद्य शिष्य के जीवन क्या प्रभाव पड़ा ? शिष्य सामान्य लोगों से दूर रहने लगा । शिष्य रोगियों की निस्वार्थ सेवा में जुट गया । शिष्य आर्थिक रूप से धनी हो गया । शिष्य रोगियों की आर्थिक मदद करने लगा रोगी की सेवा में संलग्न होना वैद्य शिष्य की किस विशेषता प्रकाश डालता है ? वे एक परिश्रमी चिकित्सक थे । बे रोगियों से प्रेम करते थे । वे गरीबों के मसीहा थे । वे एक कर्तव्यनिष्ठ व्यक्ति थे । वैद्य द्वारा गुरु के चरण स्पर्श कर रोगी की तीमारदारी के लिए जाना क्यों उचित था ? क्योंकि वैद्य ने गुरुको आदर भी प्रदान किया और अपना कर्तव्य भी निभाया । क्योंकि वह गुरु को प्रसन्न करने में तथा गुरु के सामने दिखावा करने में रहा । क्योंकि वह गुरु को अपनी व्यस्तता दिखाने में रहा । क्योंकि वैद्य ने स्पष्ट कर दिया कि वह दुनियादारी दिखाने में सिद्धस्थ है । ए .",
