    "hi": "निम्नलिखित पठित गद्यांश को ध्यानपूर्वक पूछे गए प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : ठ अब भाई साहब बहुत कुछ नरम गए थे । कई बार मुझे डाँटने का अवसर पा कर भी उन्होंने धीरज से काम लिया । शायद अब वह खुद समझने लगे थे कि मुझे डाँटने का अधिकार उन्हें नहीं रहा, या रहा भी, तो बहुत कम । मेरी स्वच्छंदता भी बढ़ी । मैं उनकी सहिष्णुता का अनुचित लाभ उठाने लगा । मुझे कुछ ऐसी धारणा हुई कि मैं पास ही हो जाऊँगा, पढ़ूँ या न पढ़ूँ, मेरी तकदीर बलवान है, इसलिए भाई साहब के डर से जो थोड़ा बहुत लिया करता था, वह भी बंद हुआ । मुझे कनकौए उड़ाने का नया शौक पैदा हो गया था और अब सारा समय पतंगबाज़ी की ही भेंट होता था । फिर भी मैं भाई साहब का अदब करता था और उनकी बचाकर कनकौए उड़ाता था । माँझा देना, कन्ने बाँधना, पतंग टूर्नामेंट की तैयारियाँ आदि समस्याएँ गुप्त रूप से हल की जाती थीं । मैं भाई साहब को यह संदेह न करने देना चाहता था कि उनका सम्मान और लिहाज़ मेरी नज़रों में कम हो गया है । (ए) भाई साहब के नरम पड़ने का क्या कारण था ? ( ) वह थक गए थे । ( ) वे समझदार हो गए थे । ( ) छोटे भाई का परिणाम उनसे ज़्यादा अच्छा आता था । ( ) बड़े भाई का स्वभाव गया था । लेखक बड़े भाई की सहिष्णुता का क्या लाभ उठाने लगे थे ? ( ) उनकी बात अनसुनी कर देते । ( ) लेखक की स्वच्छंदता गई । ( ) लेखक उनका अपमान करने लगे ॥ ( ) लेखक स्वयं निर्णय लेने लगे । लेखक को क्या नया शौक पैदा हुआ ? ( ) कनकौए उड़ाने का ( ) कंचे खेलने का ( ) देर तक सोने का ( ) कझ्ने बाँधने का पतंग संबंधी समस्याओं का हल लेखक गुप्त रूप से क्यों करते थे ? ( ) छात्रावास में पतंग उड़ाने की इजाजत नहीं थी । ( ) म",
