    "hi": "॥_ रे (व्यावहारिक व्याकरण) निर्देशानुसार “रचना के आधार वाक्य भेद” आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के उत्तर लिखिए : (क) हमारे पिताजी तड़के उठते और पूजा करने बैठ जाते थे। (सरल वाक्य में बदलिए) (ख) पिताजी आटे की गोलियों को लेकर गंगाजी की ओर चल पड़ते (संयुक्त वाक्य में बदलिए) (ग) आँँधी के कुछ दूर निकल जाने हम लोग घर की ओर दौड़े । (मिश्र वाक्य में बदलिए) (घ) वह आटे की गोलियाँ मछलियों को खिलाते हम हँसा करते थे (आश्रित उपवाक्य छाँटकर उसका भेद भी लिखिए) (ड) अज्ञेय जी ने कई नौकरियाँ की और छोड़ी । (रचना की दृष्टि से वाक्य भेद लिखिए) निर्देशानुसार “वाच्य” आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के उत्तर लिखिए : (क) भाववाच्य की क्या पहचान होती है ? उदाहरण सहित लिखिए। (ख) सुमित्रानंदन पंत ने प्रदेश में होने वाली वर्षा का बड़ा ही मनोहारी किया है । (कर्मवाच्य में बदलिए) (ग) दुकानदार द्वारा एक ग्राहक को सामान दिखाया जा रहा था । (कर्तृवाच्य में बदलिए) (घ) ऐसी सर्दी में रात भर कैसे बैठेंगे । (भाववाच्य में बदलिए) (छ) मोहन ने रोटी के एक बड़े ग्रास को खाने की कोशिश की। (वाच्य पहचानकर भेद बताइए) ॥_ रे निर्देशानुसार 'पद परिचय' आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के रेखांकित पदों का पद परिचय दीजिए : (क) शाहनी का घर से निकलना छोटी सी बात नहीं है। (ख) शाहनी अस्फुट से बोली। (ग) शाहनी ने दुपट्टे से आँखें पोंछी । (घ) आज वह अकेली हो गई है। (ड) इस दरिया के किनारे वह दुलहिन बनकर उतरी थी। निर्देशानुसार “अलंकार! आधारित निम्नलिखित पाँच प्रश्नों में से किन्हीं चार प्रश्नों की काव्य पंक्तियों",
