    "hi": "?.. . निम्नलिखित गद्यांश को ध्यानपूर्वक उस आधारित दिए गए प्रश्नों के उपयुक्त उत्तर लिखिए : अपना और पराया दुख दोनों क्रोध को बढ़ाने वाले हैं। इसमें अपने स्वार्थ के लिए क्रोध संयम ही उपयुक्त समझा गया है । इसका मुख्य कारण यही है कि दूसरे के लिए किया जाने वाला क्रोध तो दूसरे के दुख से व्याकुल होने ही होता है। जो सगे संबंधियों या मित्रों के लिए किए गए क्रोध से भी उत्तम कोटि का माना जा सकता है ऐसे ही क्रोध का उदाहरण काव्य जगत का जगमगाता “रामायण” है, जिसकी रचना आदिकवि वाल्मीकि ने की थी । व्याध द्वारा क्रौंच पक्षी को मारने वाल्मीकि के मुख से क्रोध रूपी काव्यधारा निकली थी जिससे आगे चलकर “रामायण” की रचना हुई । यहाँ वाल्मीकि ने बिना किसी भेदभाव के, कल्याण के लिए व्याध को शाप दिया जो व्याध की कठोरता का दंड और साहित्य का अनूठा ग्रंथ बना । इसी प्रकार शिशुपाल के अत्याचार सीमा पार कर गए तो श्रीकृष्ण को क्रुद्ध होकर उसे दंडित करके, समाज के कल्याण का बीड़ा उठाना पड़ा । इन दोनों ही परिस्थितियों में क्षमा अपनी सीमा समाप्त कर चुकी थी। उस समय यदि ऐसा न किया जाता तो समाज में निराशा और अत्याचार का बोल बाला बढ़ता ही चला जाता । आशा और उत्साह सदा के लिए समाप्त हो जाते । इन परिस्थितियों में के उद्धार के लिए, पवित्र भावों की रक्षा के लिए, अन्याय का विरोध करना जरूरी हो जाता है । ऐसा क्रोध में विश्वास को बढ़ाता है। संसार में शांति की स्थापना करता है। अत: इस प्रकार के क्रोध को पवित्र या पावन क्रोध की संज्ञा दी गई है। राम और कृष्ण ने ऐसा ही कालाम्निसदृश अर्थात् मृत्यु के समान भयंकर क्रोध कर तत्कालीन समाज की रक्षा की थी। ह",
