    "hi": "॥_ रे (व्यावहारिक व्याकरण) निर्देशानुसार “रचना के आधार वाक्य भेद” आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के उत्तर लिखिए : (क) पिताजी हमें उठाते और पूजा में बिठा लेते। (सरल वाक्य में बदलिए) (ख) पिताजी के ज़मीन लेटते ही हम उनकी छाती चढ़ जाते थे। (संयुक्त वाक्य में बदलिए) (ग) बरणखा बंद होते ही बाग में बहुत से बिच्छू आए। (मिश्र वाक्य में बदलिए) (घ) वह घर की ओर लौटने लगते हमें झूला झुलाते थे। (आश्रित उपवाक्य छाँटकर उसका भेद भी लिखिए) (ड) मैं चाहती थी कि इस सारे परिदृश्य को अपने भीतर समेट लूँ। (रचना की दृष्टि से वाक्य का भेद पहचानकर लिखिए) निर्देशानुसार “वाच्य” आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के उत्तर लिखिए : (क) कवियों ने वर्षा ऋतु को अपनी रचनाओं में महत्त्वपूर्ण स्थान प्रदान किया है। (कर्मवाच्य में बदलिए) (ख) लहतनासिंह द्वारा दूसरी बाल्टी भरकर उसके हाथ में दे दी गई। (कर्तृवाच्य में बदलिए) (ग) मैं इस पेड़ नहीं सकता । (भाववाच्य में बदलिए) (घ) भाववाच्य की क्या पहचान होती है ? उदाहरण सहित लिखिए। (ड) मोहन ने रोटी का एक टुकड़ा मुँह में रख लिया । (वाच्य पहचानकर भेद लिखिए) ॥_ रे निर्देशानुसार 'पद परिचय' आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के रेखांकित पदों का पद परिचय दीजिए : (क) कौन नहीं है आज वहाँ ? (ख) इस कहानी में मनुष्य के भीतर का ढूंद्व है। (ग) उसने राहुल की ओर देखा और हल्के से हँस पड़ी । (घ) शाहनी ने उठाई। (ड). शाहनी ने अंजलि भरकर सूर्य देवता को नमस्कार किया निर्देशानुसार “अलंकार! आधारित निम्नलिखित पाँच प्रश्नों में से किन्हीं चार प्रश्नों की काव्य पंक्तियों म",
