    "hi": "निम्नलिखित पठित गद्यांश आधारित बहुविकल्पी प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : इस दृष्टि से यह और सराहनीय प्रयास था केवल एक चीज़ की कसर थी जो देखते ही खटकती थी । नेताजी की आँखों चश्मा नहीं था । यानी चश्मा तो था, लेकिन संगमरमर का नहीं था एक सामान्य और सचमुच के चश्मे का चौड़ा काला फ्रेम मूर्ति को पहना दिया गया था हालदार साहब पहली बार इस कस्बे से गुज़रे और चौराहे पान खाने रुके तभी उन्होंने इसे लक्षित किया और उनके चेहरे एक कौतुकभरी मुसकान फैल गई वाह भई ! यह आइडिया भी ठीक है । मूर्ति की, लेकिन चश्मा रियल ! जीप कस्बा छोड़कर आगे गई भी हालदार साहब इस मूर्ति के बारे में ही सोचते रहे और अंत में इस निष्कर्ष पहुँचे कि कुल मिलाकर कस्बे के नागरिकों का यह प्रयास सराहनीय ही कहा जाना चाहिए । महत्त्व मूर्ति के रंग रूप या कद का नहीं, उस भावना का है वरना तो देश भक्ति भी आजकल मज़ाक की चीज़ होती जा रही है। कस्बे के नागरिकों के किस प्रयास को और सराहनीय कहा गया है ?",
