    "hi": "पूरक पाठ्य पुस्तक के निर्धारित पाठों आधारित निम्नलिखित तीन प्रश्नों में से किन्हीं दो प्रश्नों के उत्तर लगभग 60 शब्दों में लिखिए : (क) 'माता का अँचल'” पाठ में वर्णित मूसन तिवारी वाली घटना का संक्षिप्त करते हुए लिखिए कि इस घटना से बाल मनोविज्ञान के विषय में क्या जानकारी मिलती है ? (ख) 'साना साना हाथ जोड़ि! पाठ से उद्धृत “जाने कितना ऋण है हम इन नदियों का' कथन के संदर्भ में मानव जीवन में नदियों के महत्त्व का कीजिए । (ग) मैं क्यों लिखता हूँ” पाठ के आधार पर अनुभव और अनुभूति के अंतर को स्पष्ट करते हुए लिखिए कि लेखक को लेखन में दोनों में से कौन अधिक प्रभावित करता है और क्यों ? (रचनात्मक लेखन) । . (क) जनित रोगों से बचने के लिए अपने आस पास साफ सफाई रखने और जल भराव को रोकने की जानकारी देते हुए नगर निगम द्वारा जनहित में जारी एक आकर्षक विज्ञापन लगभग शब्दों में तैयार कीजिए । ट अथवा (ख) मनवांछित कॉलेज में प्रवेश पाने वाले अपने मित्र को बधाई देते हुए लगभग शब्दों में एक संदेश लिखिए",
