    "hi": "रे ख (व्यावहारिक व्याकरण) निर्देशानुसार “रचना के आधार वाक्य भेद” आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के उत्तर लिखिए : (क) पिताजी कुछ झुँझलाते और हमारे पर त्रिपुंड कर देते थे। (सरल वाक्य में बदलिए) (ख) उनके बनावटी रोने हम खिल खिलाकर हँसने लगते । (संयुक्त वाक्य में बदलिए) (ग) हम लोगों के न मिलने तिवारी जी सीधे पाठशाला में चले गए । (मिश्र वाक्य में बदलिए) (घ) हम उनकी लंबी लंबी मूँछे उखाड़ने लगते वह हमारे हाथ चूम लेते। (आश्रित उपवाक्य छाँटकर उसका भेद भी लिखिए) (ड) आँखों और आत्मा को सुख देने वाले नज़ारे दिखाई दे रहे थे। (रचना की दृष्टि से वाक्य का भेद पहचानकर लिखिए) निर्देशानुसार “वाच्य” आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के उत्तर लिखिए : (क) सामान्य व्यक्तियों ने भी अपने से बड़े बड़े साम्राज्य खड़े कर दिए हैं। (कर्मवाच्य में बदलिए) (ख) लहतनासिंह द्वारा दो कंबल ओढ़कर सोया गया (कर्तृवाच्य में बदलिए) (ग) (घ) (ड) बच्चा धीरे धीरे चलता है। (भाववाच्य में बदलिए) सिद्धेश्वरी ने खाने की थाली सामने रख दी । (वाच्य पहचानकर भेद लिखिए) भाववाच्य की क्या पहचान होती है ? उदाहरण सहित लिखिए। ॥_ रे निर्देशानुसार 'पद परिचय' आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के रेखांकित पदों का पद परिचय दीजिए : (क) बैलों की घंटियाँ टन टन उठती हैं। (ख) शाहनी ने लंबी साँस ली। (ग) शाहनी कुएँ की ओर बढ़ी । (घ) शेरा लौट गया उसे कुछ पता नहीं । (ड) बड़ी बूढ़ियाँ शाहनी के गले लगीं और चल पड़ी । निर्देशानुसार “अलंकार! आधारित निम्नलिखित पाँच प्रश्नों में से किन्हीं चार प्रश्नों की काव्य पंक्तियों में अ",
