    "hi": "निम्नलिखित पठित गद्यांश आधारित बहुविकल्पी प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : पंछी, मानव, पशु, नदी, पर्वत, समंदर आदि की इसमें बराबर की हिस्सेदारी है । यह और बात है कि इस हिस्सेदारी में मानव जाति ने अपनी बुद्धि से बड़ी बड़ी दीवारें खड़ी कर दी हैं । पहले पूरा परिवार एक परिवार के समान था, अब टुकड़ों में बँटकर एक दूसरे से दूर हो चुका है । पहले बड़े बड़े दालानों आँगनों में मिलजुलकर रहते थे, अब छोटे छोटे डिब्बे जैसे घरों में जीवन सिमटने लगा है । बढ़ती हुई आबादियों ने समंदर को पीछे सरकाना शुरू कर दिया है, पेड़ों को रास्तों से हटाना शुरू कर दिया है, फैलते हुए प्रदूषण ने पंछियों को बस्तियों से भगाना शुरू कर दिया है । बारूद की विनाशलीलाओं ने वातावरण को सताना शुरू कर दिया । अब गरमी में ज़्यादा गरमी, बेवक्त की बरसातें, ज़लज़ले, सैलाब, तूफ़ान और नित नए रोग, मानव और प्रकृति के इसी असंतुलन के परिणाम हैं । नेचर की सहनशक्ति की एक सीमा होती है । नेचर के गुस्से का एक नमूना कुछ साल पहले बंबई में देखने को मिला था और यह नमूना इतना डरावना था कि बंबई निवासी डरकर अपने अपने पूजा स्थल में अपने खुदाओं से प्रार्थना करने लगे थे",
    "ans": "",
    "fig": null,
    "opts": null,
