    "hi": "आप स्वयंसेवी संस्था रोशनी' की के अध्यक्ष प्रणीति प्रणीष हैं विश्व तंबाकू निषेध दिवस' के अवसर मादक द्र॒व्यों से होने वाले नुकसान के प्रति आम लोगों को जागरूक करने के लिए संस्था दूवारा एक कार्यशाला का आयोजन किया जा रहा है । जन साधारण को इस बात की जानकारी देने के लिए एक सूचना तैयार कीजिए । अथवा ( ) आप अ.ब.स. विद्यालय के वरिष्ठ विज्ञान अध्यापिका अध्यापक प्रणीति प्रणीष हैं। आपके विद्यालय में राष्ट्रीय विज्ञान दिवस' के अवसर विज्ञान मेले का आयोजन होने वाला है । इस बारे में सभी विद्यार्थियों को जानकारी देने के लिए एक सूचना तैयार कीजिए । ?",
