    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक उस आधारित दिए गए प्रश्नों के उत्तर लिखिए : फ्रैंकलिन का प्रसिद्ध कथन है को बरबाद न करो क्योंकि जीवन इसी से बना है ।' समय ही जीवन है । जो अवसरों और संभावनाओं से भरा हुआ है। जो बुद्धिमानी से इसका उपयोग करते हैं, वे सफलता की नींव रखते हैं, जबकि समय को व्यर्थ करने वाले अधूरे कार्यों और अपूर्ण लक्ष्यों के साथ रह जाते हैं । शास्त्रों में कहा गया है, “एक एक पैसे को जोड़कर कोई धनी बनता है, और एक एक का उपयोग करके कोई विद्वान ।' समय वास्तव में सीमित संसाधन है । हम किसी एक चीज के लिए हाँ' कहते हैं, तो किसी दूसरी चीज के लिए ना' कह रहे होते हैं । प्राचीन ज्ञान भी यही सिखाता है । अवसर को समय रहते पहचानो और उसका सदुपयोग करो । मानव जीवन एक दुर्लभ उपहार है । यही जीवन हमें विवेक देता है, जो लाभकारी और सुखद के बीच अंतर करने में बनाता है । इसलिए हर का विवेकपूर्ण उपयोग आवश्यक है । जैसे विद्यार्थी परीक्षा के आने के ठीक पहले समय को अच्छी तरह समझकर पूरी निष्ठा से पढ़ाई करते हैं, वैसे ही हमें भी जीवन के हर को उद्देश्यपूर्ण बनाना चाहिए । हम अकसर कहते हैं, काश मेरे पास और समय होता ।' यह सोच हमें थकान और असंतोष की ओर ले जाती है । साथ ही, हम एक तरह की नकारात्मकता से घधिर जाते हैं । सच यह है कि हम सबको समान घंटे मिलते हैं । फ़र्क सिर्फ इस बात से पड़ता है कि हम उनका उपयोग कैसे करते हैं। विद्वानों ने सिखाया कि सफलता उन्हीं को मिलती है, जो अपने समय को केवल सबसे महत्त्वपूर्ण कार्यों में निवेश करते हैं । प्रकृति हमें हर दिन समय का समान उपहार देती है समय की कढद्र कीजिए, घड़ी की सूइयों की फुसफुसाहट को सुनिए और उसके संकेतों को समझिए",
