    "hi": "निम्नलिखित पठित गद्यांश आधारित बहुविकल्पी प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : किस्सा क्या हुआ था उसको उसके से हटाने के बाद हमने वज़ीर अली को बनारस पहुँचा दिया और तीन लाख रुपया सालाना वजीफ़ा मुकर्रर कर दिया । कुछ महीने बाद गवर्नर जनरल ने उसे कलकत्ता (कोलकाता) किया । वज़ीर अली कंपनी के वकील के पास गया जो बनारस में रहता था और उससे शिकायत की कि गवर्नर जनरल उसे कलकत्ता में क्यूँ करता है । वकील ने शिकायत की परवाह नहीं की उलटा उसे बुरा भला सुना दिया । वज़ीर अली के तो दिल में यूँ भी अंग्रेज़ों के खिलाफ कूट कूटकर भरी है उसने खंजर से वकील का काम तमाम कर दिया । वकील ने वज़ीर अली की शिकायत की परवाह क्यों नहीं की ?",
