    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक दिए गए प्रश्नों के उत्तर लिखिए : कृत्रिम वर्षा या क्लाउड सीडिंग आधुनिक विज्ञान की एक महत्त्वपूर्ण उपलब्धि है जिसके माध्यम से बादलों से इच्छानुसार वर्षा कराई जा सकती है । इस तकनीक में सिल्वर आयोडाइड या ठोस आइस जैसे रसायनों को बादलों के बहाव के साथ फैला दिया जाता है । जहाँ बारिश करानी होती है वहाँ हवा की विपरीत दिशा में इसका छिड़काव किया जाता है । ये रसायन बादलों में मौजूद जलवाष्प के कणों को संघनित (और घना) करने में सहायता करते हैं, जिससे बूँदें बनती हैं और वर्षा होती है । यह प्रक्रिया विशेष रूप से सुसज्जित विमानों या ज़मीन से दागे जाने वाले रॉकेटों के माध्यम से संपन्न की जाती है । कृत्रिम वर्षा की आवश्यकता मुख्यतः उन क्षेत्रों में होती है जहाँ सूखा पड़ता है, जल संकट होता है या कृषि के लिए पर्याप्त वर्षा नहीं होती । संयुक्त अरब अमीरात, चीन, भारत और अमेरिका जैसे देश इस तकनीक का सफलतापूर्वक उपयोग कर रहे हैं । यह तकनीक वायु प्रदूषण को कम करने, जंगल की आग बुझाने और बाँधों में जलस्तर बढ़ाने में भी सहायक सिद्ध हुई है । कहाँ और किस बादल इसे छिड़कने से बारिश की संभावना ज़्यादा होगी, इसका निर्णय मौसम वैज्ञानिक करते हैं । इसके लिए मौसम के आँकड़ों का सहारा लिया जाता है। ॥? नर कृत्रिम वर्षा के कुछ दुष्प्रभाव भी हैं । अत्यधिक रसायनों के प्रयोग से पर्यावरण प्रदूषित हो सकता है और मिट्टी की गुणवत्ता प्रभावित हो सकती है इसके अतिरिक्त यह तकनीक अत्यंत महँगी और इसकी सफलता की दर से प्रतिशत तक होती है । कुछ वैज्ञानिकों का मानना है कि यह प्राकृतिक जल को भी बाधित कर सकती है । फिर भी, जलवायु परिवर्तन के इस युग में कृत्रिम वर्षा जल सं",
