    "hi": "निम्नलिखित काव्यांश (दोहों) को दिए गए प्रश्नों के सर्वाधिक उपयुक्त विकल्पों का चयन कर लिखिए : कस्तूरी कुंडलि बसै, मृग ढूँढे माँहि । ऐसैं घटि घटि राम है, दुनियाँ देखे नाँहि ।। बिरह भुवंगम तन बसे, मंत्र न लागै कोइ । राम बियोगी ना जिवै, जिवै तो बौरा होई ।। बौरा' किसे कहा गया है ?",
