    "hi": "र्देशानुसार पदबंध' आधारित पाँच प्रश्नों में से किन्हीं चार प्रश्नों के उत्तत लिखिए : ( ) वह आधी बाँह की सफेद कमीज़ पहने था। (वाक्य में से पदबंध छाँटिए और उसका भेद भी लिखिए) ( ) निर्मला को सवेरे से लेकर रात तक खटना पड़ता था। (रेखांकित पदबंध का भेद लिखिए) ( ) ईमानदार और मेहनती लोगों को सम्मान देना चाहिए। (वाक्य में से विशेषण पदबंध चुनकर लिखिए) ( ) क्रिया पदबंध का एक उदाहरण लिखिए। ( ) किसी भी वाक्य में सर्वगाम पदबंध की पहचान कैसे की जा सकती है, उदाहरण सहित लिखिए",
