    "hi": "निम्नलिखित में से किसी एक विषय लगभग 60 शब्दों में लिखिए : ( ) आपका नाम बिमल बिमला है। अपने क्षेत्र में प्राथमिक उपचार केंद्र खुलवाने का निवेदन करते हुए नगर निगम अधिकारी को लिखिए। अथवा () आपका नाम बिमल बिमला है। आपके पिताजी का स्थानांतरण दूसरे शहर में हो गया है, अतः वह अपना वर्तमान बैंक खाता वहाँ स्थानांतरित करवाना चाहते हैं। इस संदर्भ में जानकारी प्राप्त करने हेतु बैंक प्रबंधक को लिखिए",
