    "hi": "खंड आधारित निम्नलिखित प्रश्नों में से किन्हीं तीन प्रश्नों के उत्तर लगभग 60 शब्दों में लिखिए : ( ) बड़े भाई साहब के चरित्र की वे कौन सी दो विशेषताएँ हैं जिन्होंने आपको सर्वाधिक प्रभावित किया ? कारण सहित पाठ के आधार पर लिखिए। ( ) डायरी का एक पन्ना पाठ स्वतंत्रता सेनानियों के बलिदान का ज्वलंत दस्तावेज़ है। सिद्ध कीजिए। (॥) तताँरा वामीरों कथा! पाठ में वैवाहिक संबंधों में चलने वाली परंपराओं के दुष्परिणाम का उल्लेख हुआ है। वर्तमान भारत में इस स्थिति में क्या परिवर्तन आया है ? छैलेंद्र द्वारा वर्णित कहानी सुनकर राजकपूर को फ़िल्म की असफलता का पूर्वाभास हो गया था, फिर भी उन्होंने फ़िल्म में काम करना क्यों स्वीकार किया ? पाठ के संदर्भ में अनुमानित उत्तर दीजिए",
    "ans": "",
    "fig": null,
    "opts": null,
