    "en": "",
    "hi": "निम्नलिखित गद्यांश को दिए गए प्रश्नों के सर्वाधिक उपयुक्त विकल्प चुनकर लिखिए : लेफ़्टीनेंट : हफ़्तों हो गए यहाँ खेमा डाले हुए। सिपाही भी तंग आ गए हैं। ये वज़ीर अली आदमी है या भूत, हाथ ही नहीं लगता। : उसके अफ़साने सुन के रॉबिनहुड के कारनामे याद आ जाते हैं। अंग्रेज़ों के ख़िलाफ़ उसके दिल में किस नफ़रत है। कोई पाँच महीने हुकूमत की होगी। मगर इस पाँच महीने में वो अवध के दरबार को अंग्रेज़ी असर से बिल्कुल पाक कर देने में तक़रीबन कामयाब हो गया था। लेफ़्टीनेंट : कालिंज ये सआदत अली कौन है ? हि : आसिफ़उद्दौला का भाई है। वज़ीर अली का और उसका दुश्मन। असल में नवाब आसिफ़उद्दौला के यहाँ लड़के की कोई उम्मीद नहीं थी। वज़ीर अली की पैदाइश को सआदत अली ने अपनी मौत ख़याल किया। लेफ़्टीनेंट : मगर सआदत अली को अवध के पर बिठाने में क्या मसलेहत थी ? : सआदत अली हमारा दोस्त है और बहुत ऐश पसंद आदमी है इसलिए हमें अपनी आधी मुमलिकत (ज़ायदाद, दौलत) दे दी और दस लाख रुपये नगद। अब वो भी मज़े करता है और हम भी",
