    "kind": "mcq",
    "d": 1,
    "en": "",
    "hi": "निम्नलिखित गद्यांश को ध्यानपूर्वक दिए गए प्रश्नों के उत्तर लिखिए : मन कल्पनाशील है, इसलिए सुंदर सतरंगी कल्पनाएँ बनाकर लुभाता है, मगर सच का अनुभव करना हो तो कल्पना के आसमान से उतरकर सच के धरातल आना पड़ता है। काँटे, यानी जो भी दुखद है, जो भी नकारात्मक है, उसका स्वीकार। लेकिन उन्हें तो हम अपने भीतर कहीं गहरे दबा देते हैं, उनसे बचना चाहते हैं। जीवन को अच्छे और बुरे में बाँटकर हमने खुद के साथ बड़ा अन्याय किया है। जिन्दगी आदमी की सतरंगी कल्पनाओं के सहारे नहीं चलती, उसके अपने नियम हैं, जो बिल्कुल वैज्ञानिक हैं। हमारा पूरा अस्तित्व बना तरंगों से; यह ऊर्जा का महासागर है और ऊर्जाएँ स्वभावतः एक दूसरे के विपरीत और परिपूरक होती हैं। जो विपरीत दिखाई देता है, वह दूसरे को सहारा देता है। दो विपरीत एक दूसरे को सँभालते हैं। अगर आप चाहते हैं कि सच में आपके जीवन का फूल खिले, तो काँटों से दूर रहने की आदत छोड़ दें। ज्योति अंधेरे में ही जगमगाती है। पर छेनी चलती है, तभी तो मूर्तियाँ निर्मित होती हैं। अगर कह दे कि नहीं, छेनी मुझे बर्दाश्त नहीं, मुझे काटो मत। मैं जैसा हूँ, मुझे वैसा ही रहने दो; तो अनगढ़ ही रह जाएगा। छेनी की चोट सहना उसके लिए जरूरी है। लोग काँटों से इसलिए बचते हैं कि उनके छिदने जो दुख होता है, उसकी पीड़ा सहने की उनमें शक्ति नहीं है। काँटों से निबाह करना काफी नहीं है, काँटों से उतना ही प्रेम करना होगा, जितना फूलों से। अगर आपने काँटों से प्रेम न किया, तो आप प्लास्टिक के फूल ही खरीद लाएँगे, क्योंकि उनमें काँटे नहीं होते। जिदगी के दोहरे रूप को भली भाँति पहचानिए। अगर आपने जिद की कि हम तो एक को ही पकड़कर जिएँगे, तो आपको यह भी मानना होगा कि आप एक ही पैर से, एक ही पतवार से अपनी नाव खे लेंगे। आप एक ही पतवार से नाव को खेओगे तो वह गोल गोल लगाने लगेगी। ऐसी ही जिंदगी है। दोनों पतवारों से खेकर ही इसे किनारे पहुँचाया जा सकता है",
    "ans": "",
    "fig": null,
