    "hi": "पूरक पाठ्यपुस्तक संचयन' आधारित निम्नलिखित प्रश्नों में से किन्हीं दो प्रश्नों के उत्तर लगभग 60 शब्दों में लिखिए : ( ) टहरिहर काका कहानी के माध्यम से लेखक ने पारिवारिक जीवन में बढ़ती स्वार्थपरता को उजागर किया है। सिद्ध कीजिए। ( ) क्या टोपी शुक्ला कहानी बाल मनोविज्ञान आधारित है ? तर्कपूर्ण उत्तर लिखिए। व एएएएएएएएएएएएएएएएपपफओ हल काठ ( ॥) 'परचूनिये, आढ़तीये भी अपने बच्चों को स्कूल भेजना ज़रूरी न समझते।' सपनों के से दिन पाठ से उद्धृत प्रस्तुत पंक्ति के संदर्भ में लिखिए कि तत्कालीन समय में शिक्षा के प्रति लोगों का क्या दृष्टिकोण था और इसका कया कारण हो सकता है ?",
