    "hi": "निम्नलिखित अपठित गद्यांश को ध्यानपूर्वक उस आधारित दिए गए प्रश्नों के उत्तर लिखिए ; पर्यावरण के प्रति जागरूकता पैदा करने और पृथ्वी को संरक्षित करने के लिए स्वीडन से जून को विश्व पर्यावरण दिवस आयोजित करने का सिलसिला प्रारंभ हुआ में पर्यावरण दिवस का विषय था वैश्विक प्लास्टिक प्रदूषण का अंत' । प्लास्टिक हमारे जीवन के अनेक पहलुओं में आवश्यक है मगर इसके कारण “एक बार प्रयोग होने वाली उपभोक्ता संस्कृति! और “इस्तेमाल करो और फेंको” पीढ़ी का हुआ है। मनुष्य की इस गतिविधि का नुकसान उसके साथ साथ असहाय पशु पक्षियों और प्रकृति को भी भुगतना रहा है। संयुक्त राष्ट्र पर्यावरण की एक रिपोर्ट के अनुसार एक दिन में लगभग करोड़ प्लास्टिक की बोतलों का उपयोग होता है । हम पृथ्वी प्लास्टिक कचरे की ऐसी विरासत छोड़ रहे हैं जिसका कोई अंत नहीं । शहरों में जल जमाव की समस्या का मुख्य कारण प्लास्टिक कचरा ही है। प्रतिशत प्लास्टिक जीवाश्म ईंधन से तैयार होता है जो जैविक रूप से कभी नहीं होता । लोगों में यह श्राँति है कि समस्त प्लास्टिक का पुन: उपयोग हो जाता है। देश में मात्र प्रतिशत प्लास्टिक का ही पुन: उपयोग हो रहा है और प्रतिशत प्लास्टिक कचरा जलाया जा रहा है जिससे पर्यावरण को क्षति पहुँच रही है। अजर अमर दिखने वाले दानव का वध करने के लिए लोगों को इसके समाधान का हिस्सा बनना होगा । प्लास्टिक उत्पादक उद्यमों को इसके विकल्पों को तलाशने और इसके पुनर्चक्रण ध्यान देना होगा । आम नागरिकों को अहम भूमिका निभानी होगी क्योंकि यदि नागरिकों को कर्त्तव्य समझ में आ जाएँ तो स्थिति में सुधार लाया जा सकता है। हम अपने और अपने परिजनों के लिए स्वस्थ जीवन चाहते हैं तो हमें अपनी आदतों में बदलाव लाना होगा बदलाव कठिन हो सकता है लेकिन पर्यावरण बिगाड़ने वाली इस बिल्ली के गले में घंटी बाँधनी ही होगी । , . .",
