    "hi": "प्रश्नों के सर्वाधिक उपयुक्त उत्तर वाले विकल्प चुनकर लिखिए : ठ)द कुछ समय बाद पासा गाँव में 'पशु पर्व” का आयोजन हुआ । पशु पर्व में हृष्ट पुष्ट पशुओं के प्रदर्शन के अतिरिक्त पशुओं से युवकों की शक्ति परीक्षा प्रतियोगिता भी होती है। में एक बार सभी गाँव के लोग हिस्सा लेते हैं बाद में नृत्य संगीत और भोजन का भी आयोजन होता है। शाम से सभी लोग पासा में एकत्रित होने लगे । धीरे धीरे विभिन्न कार्यक्रम शुरू हुए तताँरा का मन कार्यक्रमों में तनिक न था । उसकी व्याकुल आँखें वामीरो को ढूँढ़ने में व्यस्त थीं। नारियल के झुंड के एक पेड़ के पीछे से उसे जैसे कोई झाँकता दिखा । उसने थोड़ा और करीब जाकर पहचानने की चेष्टा की । वह वामीरो थी जो भयवश सामने आने में झिझक रही थी । उसकी आँखें तरल थीं । होंठ काँप रहे थे । तताँरा को देखते ही वह फूटकर रोने लगी । तताँरा विह्ल हुआ । उससे कुछ बोलते ही नहीं रहा था। रोने की आवाज़ लगातार ऊँची होती जा रही थी । तताँरा किंकर्त्तव्यविमूढ़ था वामीरो के रुदन के स्वरों को सुनकर उसकी माँ वहाँ पहुँची और दोनों को देखकर आग बबूला हो उठी सारे गाँव वालों की उपस्थिति में यह दृश्य उसे अपमानजनक लगा। . तताँरा किंकर्त्तव्यविमूढ़ क्यों हो गया ?",
