    "hi": "निम्नलिखित अपठित गद्यांश को ध्यानपूर्वक उस आधारित दिए गए प्रश्नों के उत्तर लिखिए ; “'किडल्टिंग” दो शब्दों के मेल से बना है 'किड” और “एडल्ट” यानि और वयस्क की संधि । इस का इस्तेमाल पिछले कुछ वर्षों से हो रहा है वास्तव में यह की जानी पहचानी गतिविधियों की ओर एक स्वाभाविक सरल वापसी है । 'किडल्टिंग” ज़िंदगी के भागमभाग में फँसे, अकेले रह गए या अवसाद से जूझ रहे लोगों को बहुत पसंद आ रहा है । पसंदीदा गतिविधियाँ करना अकसर तनाव दूर करने के लिए एकदम सही विकल्प होता है । बड़ी कंपनियाँ भी ऐसी गतिविधियों के चलन को बढ़ावा देने में तेज़ी से जुट गई हैं। लंदन और मैट्रिड में एक संवाद संग्रहालय “डोपामाइन लैंड” अपने अंदर के बच्चे को जगाने के लिए. और वयस्क अवस्था के संधिकाल की गतिविधियाँ करवाता है दिनभर मोबाइल और कंप्यूटर से ऊबे हुए कामकाजी लोग इससे दूरी बनाने के दिलचस्प बहाने खोजने लगे हैं । ऐसे में की दुनिया में वापसी उन्हें पसंद आ रही है क्योंकि इसमें वे बिना मोबाइल और कंप्यूटर वाले बीते जीवन को जीते हैं यह भी है कि “डोपामाइन लैंड” जैसी जगहें “हैप्पी हॉर्मोन्स' को भी सक्रिय कर रही हैं। आखिर कुछ तो कारण होगा कि वर्तमान में तमाम सुविधाओं के बावजूद लोग ऐसी परिस्थितियों का सामना कर रहे हैं जिसमें वे जीवन की संवेदगाओं का अहसास नहीं कर पाते",
